<script lang="ts">
    import { enhance } from "$app/forms";
    import { onMount } from "svelte";
    import { fly } from "svelte/transition";
    

    let isMobile = $state(false);
    let lidOpen = $state(false);

    let dialog: HTMLDialogElement|null = $state(null);
    let textArea: HTMLTextAreaElement|null = $state(null);
    let messageValue = $state('');

    function safeFocus(e: HTMLElement|null) {
        if (!isMobile && e) {
            e.focus();
        }
    }

    function timeStampString() {
        const date = new Date();
        const dateOptions: Intl.DateTimeFormatOptions = {
            year: 'numeric',
            month: 'long',
            day: 'numeric',
        }

        const timeOptions: Intl.DateTimeFormatOptions = {
            hour: 'numeric',
            minute: '2-digit',
            hour12: true,
        }

        const formattedDate = new Intl.DateTimeFormat('en-US', dateOptions).format(date);
        const formattedTime = new Intl.DateTimeFormat('en-US', timeOptions).format(date);

        return `${formattedDate}\n${formattedTime}\n`;
    }

    function openLetter() {

        if (messageValue.trim() == "") {
            
            let timeStamp = timeStampString();

            let finalString = `${timeStamp}\nFrom: `;

            messageValue = finalString;
              
        }  
        
        dialog?.show();
        safeFocus(textArea);
        

    }

    onMount(()=>{
        // to prevent annoying keyboard popup on mobile devices.
        isMobile = window.matchMedia("(pointer: coarse)").matches;
    })
</script>

